   if(pose){if(motion.kind==='enter'){motion.from.x=motion.to.x<.5?-.12:1.12;motion.to.x=pose.x}else if(motion.kind==='exit'){motion.from.x=pose.x;motion.to.x=pose.x<.5?-.12:1.12}else motion.from.x=motion.to.x=pose.x}
