function performanceFrame(now){if(!playing)return;if(frameClock)elapsed+=Math.min(.08,(now-frameClock)/1000);frameClock=now;if(activeActIndex>=0){const local=Math.max(0,elapsed-actStartElapsed);acts[activeActIndex].seconds=Math.max(acts[activeActIndex].seconds,local+.08);refreshVideoTimeline()}drawStage(elapsed,true);raf=requestAnimationFrame(performanceFrame)}
